$$
\begin{aligned}
E&=\frac{4}{\left(\frac{\sqrt{2}}{2}\right)}\\&=\frac{8}{\sqrt{2}}\\&=4 \sqrt{2}.
\end{aligned}
$$"] [:db/add "018e9f50-0472-569b-869e-52327dfb3a0b" :question/difficulty :question.difficulty/hard] [:db/add "018e9f50-0472-569b-869e-52327dfb3a0b" :question/answer-fields "fbafddf7-98f4-574e-afcb-9ad4325dcab4"] [:db/ensure "018e9f50-0472-569b-869e-52327dfb3a0b" :question/validate] [:db/add 17592186059672 :knowledge-point/questions "018e9f50-0472-569b-869e-52327dfb3a0b"] [:db/add "generator" :question-generator/id #uuid "50a21fc9-aa2a-5273-9421-9d7d97a4704e"] [:db/add "generator" :question-generator/script "generators/93/9337de33429f720e400d28159cee11e07a426ad39530af33b9646bd7c5af67bf/generator.py"] [:db/add 17592186059672 :knowledge-point/question-generator "generator"] [:db/ensure 17592186059672 :knowledge-point/validate] [:db/cas 17592186749214 :question/retired nil true] [:db/cas 17592186749226 :question/retired nil true] [:db/cas 17592186749243 :question/retired nil true] [:db/cas 17592186749269 :question/retired nil true]] "assertions" [["db53bbb2-3402-5e1d-9f07-2b7cd8717680" :answer/id #uuid "db53bbb2-3402-5e1d-9f07-2b7cd8717680"] ["db53bbb2-3402-5e1d-9f07-2b7cd8717680" :answer/type :answer.type/math] ["db53bbb2-3402-5e1d-9f07-2b7cd8717680" :answer/value "\frac{\sqrt{2}}{2}"] ["e7af0949-b849-537b-bf63-f4a38066ce61" :answer/id #uuid "e7af0949-b849-537b-bf63-f4a38066ce61"] ["e7af0949-b849-537b-bf63-f4a38066ce61" :answer/type :answer.type/math] ["e7af0949-b849-537b-bf63-f4a38066ce61" :answer/value "\frac{1}{4}"] ["f1585335-a414-5452-a6f5-9ec0769b80b5" :answer/id #uuid "f1585335-a414-5452-a6f5-9ec0769b80b5"] ["f1585335-a414-5452-a6f5-9ec0769b80b5" :answer/type :answer.type/math] ["f1585335-a414-5452-a6f5-9ec0769b80b5" :answer/value "2"] ["2d017e70-2af1-54e6-9041-60add084bf85" :answer/id #uuid "2d017e70-2af1-54e6-9041-60add084bf85"] ["2d017e70-2af1-54e6-9041-60add084bf85" :answer/type :answer.type/math] ["2d017e70-2af1-54e6-9041-60add084bf85" :answer/value "\frac{\sqrt{3}}{2}"] ["6f2600e4-aa04-55ea-a5b6-cd84b9452173" :answer/id #uuid "6f2600e4-aa04-55ea-a5b6-cd84